import{_ as d,o as t,c as o,ae as c}from"./chunks/framework.DQC_QtFV.js";const b=JSON.parse('{"title":"compose 与数据卷","description":"","frontmatter":{},"headers":[],"relativePath":"guide/compose.md","filePath":"guide/compose.md","lastUpdated":1793162416000}'),a={name:"guide/compose.md"};function r(s,e,l,h,i,n){return t(),o("div",null,[...e[0]||(e[0]=[c('<h1 id="compose-与数据卷" tabindex="-1">compose 与数据卷 <a class="header-anchor" href="#compose-与数据卷" aria-label="Permalink to &quot;compose 与数据卷&quot;">​</a></h1><p><code>compose.yaml</code> 描述四个服务，一个 stack 对应一个账号。除控制台的 8080 之外没有别的端口 需要发布。</p><table tabindex="0"><thead><tr><th>服务</th><th>是什么</th></tr></thead><tbody><tr><td><code>qq</code></td><td>聊天客户端（官方、未修改、无头运行）加驱动程序。持有 ptrace 权能，只为首次登录读一次数据库密钥</td></tr><tr><td><code>console</code></td><td>面板。唯一打算发布的服务，一个密码背后同时代理驱动程序 API 和实时画面</td></tr><tr><td><code>bot</code></td><td>模型：一个 agent 会话、笔记记忆，以及每条出站消息的审查</td></tr><tr><td><code>sandbox</code></td><td>模型的命令所在的沙箱：一个 exec 服务，每条命令都落到非特权用户，只有一个卷，自己不持任何密钥</td></tr></tbody></table><h2 id="数据放在哪里" tabindex="-1">数据放在哪里 <a class="header-anchor" href="#数据放在哪里" aria-label="Permalink to &quot;数据放在哪里&quot;">​</a></h2><table tabindex="0"><thead><tr><th>宿主机路径</th><th>挂载到</th><th>内容</th></tr></thead><tbody><tr><td><code>./data/driver</code></td><td><code>/data/driver</code></td><td><code>secrets/db_key</code>（0600）、<code>mirror.db</code>、<code>config.json</code></td></tr><tr><td><code>./data/bot</code></td><td><code>/data/bot</code></td><td><code>bot.db</code>、<code>pi/</code>（<code>auth.json</code> 0600）、<code>secrets/</code>、<code>stickers/</code></td></tr><tr><td><code>./workspace</code></td><td><code>/workspace</code></td><td>模型的文件，以及被截断输出的完整副本</td></tr><tr><td><code>./logs</code></td><td><code>/out</code></td><td><code>qq</code> 容器自己的日志：<code>qq.log</code>、<code>keyx.log</code>、<code>novnc.log</code></td></tr><tr><td><code>qq_profile</code>（卷）</td><td><code>/home/qq/.config/QQ</code></td><td>客户端配置：登录态、数据库、图片缓存</td></tr><tr><td><code>qq_install</code>（卷）</td><td><code>/opt/QQ</code></td><td>已安装的客户端版本</td></tr></tbody></table><p><code>./data/bot</code>、<code>./workspace</code> 和 <code>./logs</code> 要归 uid 1000（见 <a href="./quick-start.html">快速开始</a>）； 两个命名卷不需要。</p><h2 id="工作区与沙箱" tabindex="-1">工作区与沙箱 <a class="header-anchor" href="#工作区与沙箱" aria-label="Permalink to &quot;工作区与沙箱&quot;">​</a></h2><p><code>./workspace</code> 只由 bot 和 sandbox 共享，没有第三个使用者。沙箱没有别的挂载， 所以它读不到镜像副本、<code>bot.db</code> 和客户端的文件；它通往互联网的唯一出口是 bot 的出网代理： 沙箱在一个没有出栈路由的内部 compose 网络上，同一个网络上只有 bot。代理放行哪些域名， 在 <a href="./console/safety.html">安全</a> 页的 网络 卡片里审。</p><h2 id="日志可能含聊天内容" tabindex="-1">日志可能含聊天内容 <a class="header-anchor" href="#日志可能含聊天内容" aria-label="Permalink to &quot;日志可能含聊天内容&quot;">​</a></h2><p><code>./logs</code> 下的文件是整套栈运行时写下的诊断日志，可能包含聊天内容，请妥善保管，不要分享。 面板里的 <a href="./console/logs.html">日志</a> 页是另一份：它汇总驱动、机器人和面板自己的事件， 可以直接在面板里筛。</p><h2 id="更新与备份" tabindex="-1">更新与备份 <a class="header-anchor" href="#更新与备份" aria-label="Permalink to &quot;更新与备份&quot;">​</a></h2><p>备份就是复制 <code>./data</code>、<code>./workspace</code> 和两个命名卷；客户端配置（<code>qq_profile</code>）丢了要重新扫码， <code>qq_install</code> 丢了下次启动重装。更新步骤见 <a href="./updating.html">更新</a>。</p>',12)])])}const m=d(a,[["render",r]]);export{b as __pageData,m as default};
